using System;
using System.IO;
using System.Linq;
using System.IO.Compression;
using System.Text;
using Newtonsoft.Json.Linq;
using SpatialWallpaper.Content;
static class StoreChecks {
 static int failed,passed;static void Check(string name,Action run){try{run();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
 static void Assert(bool test){if(!test)throw new Exception("assertion failed");}
 static void Reject(Action action){try{action();}catch(InvalidDataException){return;}throw new Exception("invalid request accepted");}
 static void Main(string[] args){
  string dir=args[0],package=args[1];Directory.CreateDirectory(dir);var store=new ContentStore(Path.Combine(dir,"library"),Path.Combine(dir,"staging"));
  string Stage(string source){string id=Guid.NewGuid().ToString("D");File.Copy(source,Path.Combine(dir,"staging",id+".spatial"));return id;}
  JObject imported=null;Check("first-import-does-not-apply",()=>{imported=store.Import(Stage(package));Assert(store.Snapshot["works"].Count()==1&&store.Snapshot["applied"].Count()==0);});
  Check("format-routing-does-not-admit-or-fall-back-unknown-schema",()=>{Assert(ContentPackageFormat.IsLegacy(package));string hint=Path.Combine(dir,"hint.spatial");using(var zip=ZipFile.Open(hint,ZipArchiveMode.Create))using(var writer=new StreamWriter(zip.CreateEntry("manifest.json").Open()))writer.Write("{\"schema\":3}");Assert(!ContentPackageFormat.IsLegacy(hint));Reject(()=>PackageValidator.Validate(hint));});
  Check("format-routing-rejects-duplicate-manifest-before-import",()=>{string hint=Path.Combine(dir,"duplicate-manifest.spatial");using(var zip=ZipFile.Open(hint,ZipArchiveMode.Create))for(int i=0;i<2;i++)using(var writer=new StreamWriter(zip.CreateEntry("manifest.json").Open()))writer.Write("{\"schema\":2}");Reject(()=>ContentPackageFormat.IsLegacy(hint));});
  Check("duplicate-import-reuses-default-work",()=>{var a=store.Import(Stage(package));Assert((string)a["work_id"]==(string)imported["work_id"]&&store.Snapshot["works"].Count()==1&&(bool)a["duplicate"]);});
  Check("invalid-import-no-official-write",()=>{string id=Guid.NewGuid().ToString();File.WriteAllText(Path.Combine(dir,"staging",id+".spatial"),"invalid");var before=store.Snapshot.ToString();Reject(()=>store.Import(id));Assert(store.Snapshot.ToString()==before);});
  Check("reject-staging-path",()=>Reject(()=>store.Import("../outside")));
  Check("snapshot-cannot-mutate-store",()=>{var copy=store.Snapshot;copy["works"]=new JObject();Assert(store.Snapshot["works"].Count()==1);});
  Check("restart-preserves-import-without-apply",()=>{var next=new ContentStore(Path.Combine(dir,"library"),Path.Combine(dir,"staging"));Assert(next.Snapshot["works"].Count()==1&&next.Snapshot["applied"].Count()==0);});
  Check("saved-revision-is-not-applied",()=>{string work=(string)imported["work_id"],old=store.Latest(work);string revision=store.Commit(work,old,new JObject());Assert(revision!=old&&store.Latest(work)==revision&&store.Snapshot["applied"].Count()==0);Reject(()=>store.Commit(work,old,new JObject()));});
  Check("applied-record-only-explicit-exact-revision",()=>{string work=(string)imported["work_id"],r1=store.Latest(work);store.RecordApplied("primary",work,r1);string r2=store.Commit(work,r1,new JObject());Assert((string)store.Snapshot["applied"]["primary"]["revision_id"]==r1&&store.Latest(work)==r2);var next=new ContentStore(Path.Combine(dir,"library"),Path.Combine(dir,"staging"));Assert((string)next.Snapshot["applied"]["primary"]["revision_id"]==r1);});
  Check("different-build-same-name-kept-separately",()=>{var files=new System.Collections.Generic.Dictionary<string,byte[]>();using(var z=ZipFile.OpenRead(package))foreach(var e in z.Entries)using(var r=e.Open())using(var m=new MemoryStream()){r.CopyTo(m);files.Add(e.FullName,m.ToArray());}var manifest=JObject.Parse(Encoding.UTF8.GetString(files["manifest.json"]));manifest["editable"]=!(bool)manifest["editable"];manifest["build_id"]=PackageValidator.Identity(manifest);files["manifest.json"]=Encoding.UTF8.GetBytes(manifest.ToString());string path=Path.Combine(dir,"other.spatial");using(var z=ZipFile.Open(path,ZipArchiveMode.Create))foreach(var p in files)using(var s=z.CreateEntry(p.Key).Open())s.Write(p.Value,0,p.Value.Length);var other=store.Import(Stage(path));Assert((string)other["build_id"]!=(string)imported["build_id"]&&store.Snapshot["works"].Count()==2&&store.Snapshot["builds"].Count()==2);});
  string originalWork=(string)imported?["work_id"];
  Check("controlled-empty-data-subset",()=>{var scene=PackageValidator.Validate(package).Scene;scene["effects"]=new JArray();SpatialWallpaper.Sdk.SceneData.Validate(scene);});
  Check("reject-texture-above-measured-file-limit-before-expansion",()=>{byte[] bytes=File.ReadAllBytes(package);int eocd=bytes.Length-22,position=(int)BitConverter.ToUInt32(bytes,eocd+16);bool found=false;while(position<eocd&&BitConverter.ToUInt32(bytes,position)==0x02014b50){int n=BitConverter.ToUInt16(bytes,position+28),extra=BitConverter.ToUInt16(bytes,position+30),comment=BitConverter.ToUInt16(bytes,position+32);string name=Encoding.UTF8.GetString(bytes,position+46,n);if(name.EndsWith(".stex")){Array.Copy(BitConverter.GetBytes(PackageValidator.MaxTextureFile+1),0,bytes,position+24,4);found=true;break;}position+=46+n+extra+comment;}Assert(found);string path=Path.Combine(dir,"oversized-texture.spatial");File.WriteAllBytes(path,bytes);Reject(()=>PackageValidator.Validate(path));});
  Check("controlled-rejects-callback-kind",()=>{var scene=PackageValidator.Validate(package).Scene;scene["effects"]=new JArray(new JObject{["kind"]="Awake",["node"]=0});Reject(()=>SpatialWallpaper.Sdk.SceneData.Validate(scene));});
  Check("controlled-rejects-unbound-signal-property",()=>{var scene=PackageValidator.Validate(package).Scene;scene["effects"]=new JArray(new JObject{["kind"]="signal",["node"]=0,["signal"]="flicker",["seed"]=0,["materials"]=new JArray(new JObject{["material"]=0,["property"]="_ArbitraryCallback",["type"]="float",["basis"]=new JArray(1,1,1,1),["gain"]=1}),["lights"]=new JArray()});Reject(()=>SpatialWallpaper.Sdk.SceneData.Validate(scene));});
  Check("apply-fixes-target-and-publishes-after-first-frame",()=>{var view=new Presentation();var coordinator=new ContentCoordinator(store,view);string accepted=store.Latest(originalWork);var pending=coordinator.ApplyAsync("primary",originalWork,System.Threading.CancellationToken.None);Assert(!pending.IsCompleted);string later=store.Commit(originalWork,accepted,new JObject());view.Ready.SetResult(true);var result=pending.GetAwaiter().GetResult();Assert((bool)result["succeeded"]&&(string)result["revision_id"]==accepted&&(string)store.Snapshot["applied"]["primary"]["revision_id"]==accepted&&store.Latest(originalWork)==later&&!view.Static);});
  Check("first-frame-failure-restores-old-exact-revision",()=>{string old=(string)store.Snapshot["applied"]["primary"]["revision_id"];var view=new Presentation{FailFrames=1};view.Ready.SetResult(true);var coordinator=new ContentCoordinator(store,view);var result=coordinator.ApplyAsync("primary",originalWork,System.Threading.CancellationToken.None).GetAwaiter().GetResult();Assert(!(bool)result["succeeded"]&&(bool)result["restored"]&&(string)store.Snapshot["applied"]["primary"]["revision_id"]==old&&view.Loads==2&&!view.Static);});
  Check("recovery-failure-retains-static-and-old-record",()=>{string old=(string)store.Snapshot["applied"]["primary"]["revision_id"];var view=new Presentation{FailFrames=2};view.Ready.SetResult(true);var result=new ContentCoordinator(store,view).ApplyAsync("primary",originalWork,System.Threading.CancellationToken.None).GetAwaiter().GetResult();Assert(!(bool)result["succeeded"]&&!(bool)result["restored"]&&view.Static&&(string)store.Snapshot["applied"]["primary"]["revision_id"]==old);});
  Check("publish-failure-and-recovery-failure-retains-static",()=>{string old=(string)store.Snapshot["applied"]["primary"]["revision_id"];FileStream locked=null;var view=new Presentation();view.Ready.SetResult(true);view.OnFrame=number=>{if(number==1)locked=new FileStream(Path.Combine(dir,"library/index.json"),FileMode.Open,FileAccess.Read,FileShare.None);else throw new IOException("old-first-frame-failure");};try{var result=new ContentCoordinator(store,view).ApplyAsync("primary",originalWork,System.Threading.CancellationToken.None).GetAwaiter().GetResult();Assert(!(bool)result["succeeded"]&&(string)result["failure_phase"]=="publish-applied"&&!(bool)result["restored"]&&view.Static&&(string)store.Snapshot["applied"]["primary"]["revision_id"]==old);}finally{locked?.Dispose();}});
  Check("first-apply-failure-keeps-empty-state",()=>{var view=new Presentation{FailFrames=1};view.Ready.SetResult(true);var result=new ContentCoordinator(store,view).ApplyAsync("new-display",originalWork,System.Threading.CancellationToken.None).GetAwaiter().GetResult();Assert(!(bool)result["succeeded"]&&store.Snapshot["applied"]["new-display"]==null&&!view.Static);});
  Check("invalid-display-does-not-wedge-coordinator",()=>{var view=new Presentation();view.Ready.SetResult(true);var coordinator=new ContentCoordinator(store,view);try{coordinator.ApplyAsync(null,originalWork,System.Threading.CancellationToken.None).GetAwaiter().GetResult();}catch(ArgumentException){}var next=coordinator.ApplyAsync("primary",originalWork,System.Threading.CancellationToken.None).GetAwaiter().GetResult();Assert((bool)next["succeeded"]);});
  Check("startup-restores-only-current-display-exact-revision",()=>{var view=new Presentation();view.Ready.SetResult(true);store.RecordApplied("second-display",originalWork,store.Latest(originalWork));string error=ContentStartupRecovery.RestoreAsync(store,"second-display",view).GetAwaiter().GetResult();Assert(error==null&&view.Loads==1);var empty=new Presentation();Assert(ContentStartupRecovery.RestoreAsync(store,"no-record",empty).GetAwaiter().GetResult()==null&&empty.Loads==0);});
  Check("startup-first-frame-failure-cleans-up-and-allows-next-apply",()=>{var before=store.Snapshot.ToString();var view=new Presentation{FailFrames=1};view.Ready.SetResult(true);Assert(ContentStartupRecovery.RestoreAsync(store,"primary",view).GetAwaiter().GetResult()=="startup-content-recovery-failed"&&view.Unloads==1&&store.Snapshot.ToString()==before);var result=new ContentCoordinator(store,view).ApplyAsync("primary",originalWork,System.Threading.CancellationToken.None).GetAwaiter().GetResult();Assert((bool)result["succeeded"]);});
  Check("startup-load-failure-cleans-up-and-allows-next-apply",()=>{var view=new Presentation{FailLoads=1};view.Ready.SetResult(true);Assert(ContentStartupRecovery.RestoreAsync(store,"primary",view).GetAwaiter().GetResult()=="startup-content-recovery-failed"&&view.Unloads==1);var result=new ContentCoordinator(store,view).ApplyAsync("primary",originalWork,System.Threading.CancellationToken.None).GetAwaiter().GetResult();Assert((bool)result["succeeded"]);});
  Check("page-token-invalidated-by-publish",()=>{var first=store.Page("primary");string work=((JObject)first["state"]["works"]).Properties().First().Name;store.Commit(originalWork,store.Latest(originalWork),new JObject());Reject(()=>store.Page("primary",work,(string)first["page"]["snapshot"]));Assert(((JObject)store.Page("primary")["state"]["works"]).Count==2);});
  Check("library-status-does-not-call-static-or-empty-playing",()=>{var state=store.Snapshot;Assert(ContentLibraryStatus.Row(state,"primary",originalWork,false,true).Contains("静态画面"));Assert(ContentLibraryStatus.Row(state,"primary",originalWork,false,false).Contains("未播放"));Assert(!ContentLibraryStatus.Row(state,"primary",originalWork,false,true).Contains("正在播放"));Assert(ContentLibraryStatus.Row(state,"primary",originalWork,true,false).Contains("正在播放"));});
  Console.WriteLine(passed+" passed; "+failed+" failed");Environment.Exit(failed==0?0:1);
 }
 sealed class Presentation:IContentPresentation {
  public readonly System.Threading.Tasks.TaskCompletionSource<bool> Ready=new System.Threading.Tasks.TaskCompletionSource<bool>();public int FailFrames,FailLoads,Loads,Frames,Unloads;public bool Static;public Action<int> OnFrame;
  public System.Threading.Tasks.Task HoldStaticAsync(){Static=true;return System.Threading.Tasks.Task.CompletedTask;}
  public System.Threading.Tasks.Task UnloadAsync(){Unloads++;return System.Threading.Tasks.Task.CompletedTask;}
  public System.Threading.Tasks.Task LoadAsync(ValidatedPackage package,JObject revision,System.Threading.CancellationToken cancellation){Loads++;cancellation.ThrowIfCancellationRequested();if(FailLoads-->0)throw new IOException("load-failed");return System.Threading.Tasks.Task.CompletedTask;}
  public async System.Threading.Tasks.Task FirstFrameAsync(System.Threading.CancellationToken cancellation){await Ready.Task;cancellation.ThrowIfCancellationRequested();OnFrame?.Invoke(++Frames);if(FailFrames-->0)throw new IOException("first-frame-failed");}
  public void ReleaseStatic(){Static=false;}
 }
}
